// Find best matching transcript for the client
const payload = $('Webhook — Process Client Call').first().json.body;
const clientName = (payload.client_name || '').toLowerCase().trim();
const clientEmail = (payload.client_email || '').toLowerCase().trim();

const transcriptsRaw = $input.first().json;
const transcripts = transcriptsRaw.data?.transcripts || transcriptsRaw.transcripts || [];

if (!transcripts.length) {
  return [{ json: { match: null, match_score: 0 } }];
}

// Score each transcript
const scored = transcripts.map(t => {
  let score = 0;
  const title = (t.title || '').toLowerCase();
  const participants = (t.participants || []).map(p => p.toLowerCase());
  const organizer = (t.organizer_email || '').toLowerCase();

  // Title contains client name (fuzzy)
  if (title.includes(clientName)) score += 50;
  // Partial match (first word of client name)
  else if (clientName.split(' ').some(word => word.length > 3 && title.includes(word))) score += 30;

  // Title contains onboarding/briefing keywords
  if (title.includes('onboarding') || title.includes('briefing') || title.includes('discovery')) score += 20;

  // Email match in participants or organizer
  if (clientEmail && (participants.includes(clientEmail) || organizer === clientEmail)) score += 40;

  // Recency boost (newer = better)
  if (t.date) {
    const daysAgo = (Date.now() - (parseInt(t.date) > 1e10 ? parseInt(t.date) : parseInt(t.date) * 1000)) / (1000 * 60 * 60 * 24);
    if (daysAgo < 7) score += 15;
    else if (daysAgo < 30) score += 10;
    else if (daysAgo < 90) score += 5;
  }

  return { ...t, score };
});

// Sort by score descending
scored.sort((a, b) => b.score - a.score);
const best = scored[0];

if (best.score >= 30) {
  return [{ json: { match: best, match_score: best.score, transcript_id: best.id, title: best.title } }];
} else {
  return [{ json: { match: null, match_score: 0, best_candidate: best.title, best_score: best.score } }];
}

// ============================================================
// Extract structured client context from Fireflies meeting data
// Combines AI summary + transcript analysis into call_context JSON
// ============================================================

const matchData = $('Find Best Match').first().json;
const summaryData = $('Get Meeting Summary').first().json;
const transcriptData = $('Get Full Transcript').first().json;

const summary = (summaryData.data && summaryData.data.transcript && summaryData.data.transcript.summary) || {};
const sentences = (transcriptData.data && transcriptData.data.transcript && transcriptData.data.transcript.sentences) || [];

// Calculate duration from sentences
let durationMinutes = 0;
if (sentences.length > 0) {
  const lastSentence = sentences[sentences.length - 1];
  durationMinutes = Math.round((lastSentence.end_time || 0) / 60);
}

const agencyKeywords = ['smashed', 'agency', 'team'];
const clientStatements = [];
const contentPreferences = [];
const competitiveContext = [];
const budgetContext = [];
const painPoints = [];

const contentKeywords = ['content', 'video', 'ugc', 'creator', 'ad', 'ads', 'creative', 'style', 'tone', 'vibe', 'aesthetic', 'look', 'feel', 'brand'];
const competitiveKeywords = ['competitor', 'competition', 'market', 'industry', 'similar', 'like them', 'they do', 'their ads', 'brand like'];
const budgetKeywords = ['budget', 'spend', 'roas', 'roi', 'cost', 'cpa', 'cac', 'return', 'revenue', 'target', 'goal', 'kpi'];
const painKeywords = ['problem', 'issue', 'challenge', 'struggle', 'difficult', 'pain', 'frustrat', 'fail', 'not working', 'doesnt work', "doesn't work", 'tried', 'waste'];

for (const sentence of sentences) {
  const text = (sentence.text || '').toLowerCase();
  const speaker = (sentence.speaker_name || '').toLowerCase();
  if (text.length < 20) continue;
  const isAgency = agencyKeywords.some(k => speaker.includes(k));
  if (!isAgency) {
    if (contentKeywords.some(k => text.includes(k))) contentPreferences.push(sentence.text);
    if (competitiveKeywords.some(k => text.includes(k))) competitiveContext.push(sentence.text);
    if (budgetKeywords.some(k => text.includes(k))) budgetContext.push(sentence.text);
    if (painKeywords.some(k => text.includes(k))) painPoints.push(sentence.text);
    if (text.length > 50) clientStatements.push(sentence.text);
  }
}

const limitArr = (arr, max) => arr.slice(0, max);

let actionItems = [];
if (summary.action_items) {
  if (typeof summary.action_items === 'string') {
    actionItems = summary.action_items.split('\n').filter(i => i.trim().length > 0);
  } else if (Array.isArray(summary.action_items)) {
    actionItems = summary.action_items;
  }
}

let keywords = [];
if (summary.keywords) {
  if (typeof summary.keywords === 'string') {
    keywords = summary.keywords.split(',').map(k => k.trim()).filter(k => k.length > 0);
  } else if (Array.isArray(summary.keywords)) {
    keywords = summary.keywords;
  }
}

const callContext = {
  meeting_title: matchData.meeting_title || '',
  meeting_date: matchData.meeting_date || '',
  duration_minutes: durationMinutes || (matchData.duration ? Math.round(matchData.duration / 60) : 0),
  overview: summary.overview || '',
  action_items: actionItems,
  keywords: keywords,
  client_statements: limitArr(clientStatements, 15).join(' | '),
  content_preferences: limitArr(contentPreferences, 10).join(' | '),
  competitive_context: limitArr(competitiveContext, 8).join(' | '),
  budget_context: limitArr(budgetContext, 5).join(' | '),
  pain_points: limitArr(painPoints, 8).join(' | '),
  full_summary: summary.shorthand_bullet || ''
};

return [{
  json: {
    call_context: callContext,
    call_context_json: JSON.stringify(callContext, null, 2),
    project_id: $('Webhook \u2014 Process Client Call').first().json.body.project_id || '',
    client_name: $('Webhook \u2014 Process Client Call').first().json.body.client_name || '',
    transcript_id: matchData.transcript_id,
    match_score: matchData.match_score
  }
}];

