const response = $input.first().json;
const ctx = $('Extract Client Context').first().json;

let requirements = {
  niches: ['UGC'],
  budget_max: 5000,
  count: 5,
  brand_name: ctx.client_name || '',
  location: 'India',
  languages: ['English', 'Hindi'],
  source: 'fireflies_auto_scout',
  project_id: ctx.project_id || ''
};

try {
  let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(text);

  if (parsed.niches && parsed.niches.length > 0) requirements.niches = parsed.niches;
  if (parsed.budget_per_video) requirements.budget_max = parsed.budget_per_video;
  if (parsed.num_creators_needed) requirements.count = parsed.num_creators_needed;
  if (parsed.creator_preferences?.location) requirements.location = parsed.creator_preferences.location;
  if (parsed.languages) requirements.languages = parsed.languages;
  requirements.brief_summary = parsed.brief_summary || '';
  requirements.creator_preferences = parsed.creator_preferences || {};
  requirements.industry = parsed.industry || '';
} catch (e) {
  // Use defaults — still scout with generic params
  requirements.brief_summary = 'Could not parse call context, using default parameters';
}

return [{ json: { scout_request: requirements } }];

